// The turtle-art explorer: browse thousands of seeds, view them large, keep
// favorites, or watch the hex screensaver. The art itself comes from the C++
// library, compiled to WebAssembly (see bindings.cc); this file is only the
// page around it: it asks C++ for tile colors, layouts and SVGs, then draws
// and handles input.
//
// Thumbnails are generated by a background thread (worker.js), so slow
// pictures never freeze the page; this thread only draws them.
//
// Sections, in order: settings (mirrored in the URL), favorites, drawing,
// the grid of thumbnails, the large viewer, the hex screensaver, the carpet,
// keys.

import createTurtleArt from './turtle_art.js';
import { FIBONACCI, commandOf, shapeOf, sizeOf,
         toArtSettings as artSettingsOf } from './pictures.js';

const art = await createTurtleArt();
const PALETTE = art.palette();
const FAVORITES_KEY = 'turtle-art-favorites';
const DEFAULTS = {
  shape: 'hexagon', radius: 15, rows: 21, edge: 'wrap', paint: 'turtle',
  colors: 4, history: 1, steps: 15000, start: 1, minEntropy: 0.6, thumb: 160,
};
const BATCH = 60;         // Pictures added each time the end comes into view.
// Requests the worker holds at once: enough that it never waits for the
// page between pictures, few enough that a settings change is quick to
// take effect (stale requests still finish first).
const MAX_IN_FLIGHT = 2;

const $ = (id) => document.getElementById(id);

// ---- Settings: the controls, mirrored in the URL's #fragment -------------

const controls = ['shape', 'radius', 'rows', 'edge', 'paint', 'colors',
                  'history', 'steps', 'start', 'minEntropy', 'thumb'];
const textControls = ['shape', 'edge', 'paint'];  // The rest are numbers.

function readControls() {
  const s = {};
  for (const name of controls) {
    const value = $(name).value;
    s[name] = textControls.includes(name) ? value : Number(value);
  }
  return s;
}

function writeControls(s) {
  for (const name of controls) $(name).value = s[name];
}

function settingsFromHash() {
  const params = new URLSearchParams(location.hash.slice(1));
  const s = { ...DEFAULTS };
  for (const name of controls) {
    if (params.has(name)) {
      const value = params.get(name);
      s[name] = textControls.includes(name) ? value : Number(value);
    }
  }
  return s;
}

// A picture is fully described by its seed plus these knobs.
function pictureOf(s, seed) {
  return { seed, steps: s.steps, shape: s.shape, radius: s.radius,
           rows: s.rows, edge: s.edge, paint: s.paint, colors: s.colors,
           history: s.history };
}

// The C++ settings for picture `p`, using this thread's module.
const toArtSettings = (p) => artSettingsOf(art, p);

const keyOf = (p) => commandOf(p);

// ---- Favorites, kept in this browser's localStorage ----------------------

function loadFavorites() {
  try {
    return JSON.parse(localStorage.getItem(FAVORITES_KEY)) ?? [];
  } catch {
    return [];
  }
}

let favorites = loadFavorites();

function isFavorite(p) {
  return favorites.some((f) => keyOf(f) === keyOf(p));
}

function toggleFavorite(p) {
  favorites = isFavorite(p)
    ? favorites.filter((f) => keyOf(f) !== keyOf(p))
    : [...favorites, p];
  try {
    localStorage.setItem(FAVORITES_KEY, JSON.stringify(favorites));
  } catch {
    // Storage blocked (private window): favorites last for this visit only.
  }
  $('favoritesButton').textContent = `★ Favorites (${favorites.length})`;
}

// ---- Drawing --------------------------------------------------------------

// Where a picture's tiles go, from the C++ layout (see bindings.cc): tile
// centers in Grid::Tiles() order, one tile's outline, and the picture's
// bounds. Cached, since every seed with the same grid shares it.
const layoutCache = new Map();
function layoutFor(p) {
  const s = toArtSettings({ ...p, seed: 0 });
  const key = `${shapeOf(p)} ${s.radius} ${s.width} ${s.height}`;
  if (!layoutCache.has(key)) layoutCache.set(key, art.layout(s));
  return layoutCache.get(key);
}

// The palette as [red, green, blue], parsed from its CSS colors "#rrggbb".
const PALETTE_RGB = PALETTE.map((css) =>
  [1, 3, 5].map((i) => parseInt(css.slice(i, i + 2), 16)));

// Returns picture `p`'s width divided by its height.
function aspectOf(p) {
  if (shapeOf(p) === 'hexagon') {
    const { bounds } = layoutFor(p);
    return bounds.width / bounds.height;
  }
  const { width, height } = sizeOf(p);
  return width / height;
}

// Draws picture `p`'s `colors` (one Color value per tile, in Grid::Tiles()
// order) onto `canvas`, `width` CSS pixels wide.
function draw(canvas, p, colors, width) {
  if (shapeOf(p) === 'hexagon') {
    drawHexagons(canvas, layoutFor(p), colors, width);
  } else {
    drawSquares(canvas, sizeOf(p), colors, width);
  }
}

// Square tiles are pixels: write one pixel per tile (Tiles() runs row by row
// from the top left, like an image), then let the canvas scale the image.
// That stays fast at any size; filling a path of 600,000 squares (610 rows)
// froze the page.
function drawSquares(canvas, size, colors, width) {
  const image = pixelImage(size, colors, PALETTE_RGB);
  canvas.width = Math.round(width * devicePixelRatio);
  canvas.height = Math.round(canvas.width * size.height / size.width);
  const ctx = canvas.getContext('2d');
  // Enlarged tiles stay crisp squares; shrunk ones are averaged, which
  // looks better than dropping most of them.
  ctx.imageSmoothingEnabled = canvas.width < size.width;
  ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
}

// Returns an image of `size` (a picture's columns and rows) with one pixel
// per tile, colored by `palette` ([red, green, blue] per Color value).
function pixelImage(size, colors, palette) {
  const pixels = new ImageData(size.width, size.height);
  const data = pixels.data;  // 4 bytes per pixel: red, green, blue, alpha.
  for (let i = 0; i < colors.length; i++) {
    const [red, green, blue] = palette[colors[i]];
    data[4 * i] = red;
    data[4 * i + 1] = green;
    data[4 * i + 2] = blue;
    data[4 * i + 3] = 255;
  }
  const image = new OffscreenCanvas(size.width, size.height);
  image.getContext('2d').putImageData(pixels, 0, 0);
  return image;
}

// Hexagons are drawn from the layout's tile outlines. Tiles of one color go
// into one path, so each color is a single fill call. Hexagon grids are
// small enough for this (radius 150 is 68,000 tiles).
function drawHexagons(canvas, layout, colors, width) {
  const { centers, outline, bounds } = layout;
  const scale = (width * devicePixelRatio) / bounds.width;
  canvas.width = Math.round(bounds.width * scale);
  canvas.height = Math.round(bounds.height * scale);
  const ctx = canvas.getContext('2d');
  ctx.setTransform(scale, 0, 0, scale, -bounds.x * scale, -bounds.y * scale);
  const paths = PALETTE.map(() => new Path2D());
  // Slightly oversized tiles hide the seams anti-aliasing leaves.
  const grow = 1.04;
  for (let i = 0; i < colors.length; i++) {
    const path = paths[colors[i]];
    const x = centers[2 * i];
    const y = centers[2 * i + 1];
    path.moveTo(x + outline[0] * grow, y + outline[1] * grow);
    for (let c = 2; c < outline.length; c += 2) {
      path.lineTo(x + outline[c] * grow, y + outline[c + 1] * grow);
    }
    path.closePath();
  }
  paths.forEach((path, color) => {
    ctx.fillStyle = PALETTE[color];
    ctx.fill(path);
  });
}

// ---- The grid of thumbnails ----------------------------------------------

let settings = settingsFromHash();
let showingFavorites = false;
let items = [];        // {picture, colors, entropy, card} in display order.
let nextSeed = 0;
let nextFavorite = 0;  // In the favorites view: the next one to show.
let scanned = 0;
let target = 0;
let inFlight = 0;      // Requests sent to the worker, not yet answered.
let runId = 0;         // Bumped on reset, so stale answers are dropped.

function addItem(picture, result) {
  const card = document.createElement('div');
  card.className = 'card';
  const canvas = document.createElement('canvas');
  draw(canvas, picture, result.colors, settings.thumb);
  const index = items.length;
  canvas.addEventListener('click', () => openViewer(index));
  const meta = document.createElement('div');
  meta.className = 'meta';
  const label = document.createElement('span');
  label.textContent = `#${picture.seed} · ${result.entropy.toFixed(2)}`;
  label.title = `seed · interest (color entropy)\n${commandOf(picture)}`;
  const star = document.createElement('button');
  star.className = 'star';
  const updateStar = () => {
    const on = isFavorite(picture);
    star.textContent = on ? '★' : '☆';
    star.classList.toggle('on', on);
  };
  star.addEventListener('click', () => { toggleFavorite(picture); updateStar(); });
  updateStar();
  meta.append(label, star);
  card.append(canvas, meta);
  $('grid').append(card);
  items.push({ picture, colors: result.colors, entropy: result.entropy,
               card, updateStar });
}

function updateStatus() {
  $('status').textContent = showingFavorites
    ? `${items.length} of ${favorites.length} favorites`
    : `seeds ${settings.start}–${nextSeed - 1}: showing ${items.length} of ${scanned}`;
}

// Whether more pictures can come: more favorites to show, or seeds left.
function hasMore() {
  return showingFavorites ? nextFavorite < favorites.length
                          : nextSeed <= 0xffffffff;
}

// The worker that generates pictures (worker.js). `type: 'module'` lets it
// import other modules, like this file does.
const worker = new Worker(new URL('./worker.js', import.meta.url),
                          { type: 'module' });

// Asks the worker for more pictures, up to MAX_IN_FLIGHT at a time, while
// fewer than `target` are shown (or on their way): the next favorites, or
// the next seeds.
function requestPictures() {
  while (inFlight < MAX_IN_FLIGHT && items.length + inFlight < target &&
         hasMore()) {
    const picture = showingFavorites ? favorites[nextFavorite++]
                                     : pictureOf(settings, nextSeed++);
    worker.postMessage({ run: runId, picture });
    inFlight++;
  }
}

// Shows each picture the worker sends back, if it is still wanted and (when
// exploring) interesting enough, then asks for more.
worker.onmessage = ({ data }) => {
  inFlight--;
  if (data.run === runId) {
    if (showingFavorites) {
      addItem(data.picture, data);
    } else {
      scanned++;
      if (data.entropy >= settings.minEntropy) addItem(data.picture, data);
    }
    updateStatus();
  }
  requestPictures();
};

function requestMore() {
  if (showingFavorites) return;  // Favorites all come at once, see reset().
  target = items.length + BATCH;
  requestPictures();
}

function reset() {
  runId++;
  items = [];
  $('grid').replaceChildren();
  document.documentElement.style.setProperty('--thumb', `${settings.thumb}px`);
  $('copyFavorites').hidden = !showingFavorites;
  $('empty').hidden = !(showingFavorites && favorites.length === 0);
  $('favoritesButton').classList.toggle('active', showingFavorites);
  $('favoritesButton').textContent = `★ Favorites (${favorites.length})`;
  if (showingFavorites) {
    // The view switches now; favorites then appear one by one.
    nextFavorite = 0;
    target = favorites.length;
    updateStatus();
    requestPictures();
  } else {
    nextSeed = settings.start;
    scanned = 0;
    requestMore();
  }
}

// Shows the size control that fits the shape: radius for hexagons, rows
// for the shapes made of square tiles.
function showSizeControl() {
  const hexagon = $('shape').value === 'hexagon';
  $('radiusLabel').hidden = !hexagon;
  $('rowsLabel').hidden = hexagon;
}

function applyControls() {
  showSizeControl();
  settings = readControls();
  $('minEntropyValue').textContent = settings.minEntropy.toFixed(2);
  const params = new URLSearchParams();
  for (const name of controls) params.set(name, settings[name]);
  history.replaceState(null, '', `#${params}`);
  reset();
}

// Loads more when the end of the grid scrolls into view.
new IntersectionObserver((entries) => {
  if (entries.some((e) => e.isIntersecting)) requestMore();
}, { rootMargin: '600px' }).observe($('sentinel'));

for (const name of controls) $(name).addEventListener('change', applyControls);
$('minEntropy').addEventListener('input', () => {
  $('minEntropyValue').textContent = Number($('minEntropy').value).toFixed(2);
});
$('favoritesButton').addEventListener('click', toggleFavoritesView);
$('random').addEventListener('click', randomStart);

// Jumps to a random place among the 2^32 seeds.
function randomStart() {
  $('start').value = Math.floor(Math.random() * 0x100000000);
  applyControls();
}
$('copyFavorites').addEventListener('click', () => {
  navigator.clipboard.writeText(favorites.map(commandOf).join('\n'));
});

function toggleFavoritesView() {
  showingFavorites = !showingFavorites;
  reset();
}

// ---- The large viewer ------------------------------------------------------

let current = -1;

function openViewer(index) {
  current = index;
  $('viewer').hidden = false;
  showCurrent();
}

function showCurrent() {
  const item = items[current];
  const aspect = aspectOf(item.picture);
  const width = Math.min(innerWidth - 24, (innerHeight - 110) * aspect);
  draw($('big'), item.picture, item.colors, width);
  $('big').style.width = `${width}px`;
  $('info').textContent = `#${item.picture.seed} · interest ` +
    `${item.entropy.toFixed(2)} · ${current + 1}/${items.length}`;
  $('fav').textContent = isFavorite(item.picture) ? '★' : '☆';
  $('pngButtons').hidden = !hasPng(item.picture);
  $('command').textContent = commandOf(item.picture);
  // Keep more pictures coming when browsing near the end.
  if (current >= items.length - 5) requestMore();
}

function step(delta) {
  const index = current + delta;
  if (index >= 0 && index < items.length) {
    current = index;
    showCurrent();
    items[current].card.scrollIntoView({ block: 'nearest' });
  }
}

function closeViewer() {
  $('viewer').hidden = true;
}

function favoriteCurrent() {
  const item = items[current];
  toggleFavorite(item.picture);
  item.updateStar();
  showCurrent();
}

// Has the browser save `blob` as a file named `name`.
function saveFile(blob, name) {
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = name;
  link.click();
  URL.revokeObjectURL(link.href);
}

function downloadCurrent() {
  const p = items[current].picture;
  saveFile(new Blob([art.svg(toArtSettings(p))], { type: 'image/svg+xml' }),
           `turtle-art-${p.seed}.svg`);
}

// Only square tiles map exactly onto pixels, so hexagons have no PNG.
const hasPng = (p) => shapeOf(p) !== 'hexagon';

// Saves a PNG of the current picture, each tile `scale` x `scale` pixels.
function downloadPngCurrent(scale = 1) {
  const p = items[current].picture;
  if (!hasPng(p)) return;
  const name = scale === 1 ? `turtle-art-${p.seed}.png`
                           : `turtle-art-${p.seed}-${scale}x.png`;
  saveFile(new Blob([art.png(toArtSettings(p), scale)], { type: 'image/png' }),
           name);
}

function copyCurrent() {
  navigator.clipboard.writeText(commandOf(items[current].picture));
}

$('prev').addEventListener('click', () => step(-1));
$('next').addEventListener('click', () => step(1));
$('fav').addEventListener('click', favoriteCurrent);
$('download').addEventListener('click', downloadCurrent);
for (const button of $('pngButtons').querySelectorAll('button')) {
  button.addEventListener('click',
                          () => downloadPngCurrent(Number(button.dataset.scale)));
}
$('copy').addEventListener('click', copyCurrent);
$('close').addEventListener('click', closeViewer);
$('viewer').addEventListener('click', (e) => {
  if (e.target === $('viewer')) closeViewer();
});

// ---- Hex screensaver: a new animated picture every minute ----------------
//
// The animation itself comes from C++ (an SVG that animates itself with
// SMIL, see ToAnimatedSvg): the page only picks seeds and shows their SVGs.
// A picture changes after steps / SCREENSAVER_HZ seconds (600 steps at 10
// per second: one minute). A walk that loops early (see Walk) finishes
// drawing sooner and holds still until then; the next one starts from a
// clear grid.
//
// A full picture: it needs every knob, including any added later, or
// toArtSettings hands the C++ code an undefined field.
const SCREENSAVER = {
  shape: 'hexagon', radius: 9, rows: 21, edge: 'wrap', paint: 'turtle',
  colors: 4, history: 2, steps: 600,
};
const SCREENSAVER_HZ = 10;
const SCREENSAVER_MIN_INTEREST = 0.95;
// The picture's share of the screen height. Copies of it surround it, as
// many rings as it takes to fill the screen edge to edge (2 on most
// screens, 3 on ultrawide ones).
const SCREENSAVER_SCALE = 0.6;

let saverTimer = null;
let saverPicture = null;
let saverUrl = null;

// Tries random seeds until one is interesting enough. Most are not, but
// each try takes well under a millisecond at this size.
function interestingSaverPicture() {
  let picture;
  for (let tries = 0; tries < 10000; tries++) {
    picture = { ...SCREENSAVER, seed: Math.floor(Math.random() * 0x100000000) };
    if (art.generate(toArtSettings(picture)).entropy > SCREENSAVER_MIN_INTEREST) {
      break;
    }
  }
  return picture;
}

function updateSaverFavorite() {
  $('saverFav').textContent = isFavorite(saverPicture) ? '★' : '☆';
}

// Sizes the frame holding the picture to its shape, SCREENSAVER_SCALE of the
// screen height (or less, to fit the width), and returns its height in
// pixels.
function sizeSaverFrame() {
  const { bounds } = layoutFor(saverPicture);
  const height = Math.min((innerHeight - 90) * SCREENSAVER_SCALE,
                          ((innerWidth - 24) * SCREENSAVER_SCALE * bounds.height) / bounds.width);
  $('saverFrame').style.height = `${height}px`;
  $('saverFrame').style.width = `${(height * bounds.width) / bounds.height}px`;
  return height;
}

// Shows the animated SVG at `url`, plus copies of it around, so a turtle
// leaving one side can be followed into the next copy, and the art fills
// the screen. All images share one URL, so the browser plays them in step.
// CSS translate percentages are of the image's own size, hence offset /
// picture size.
function showSaverPicture(url) {
  const { bounds } = layoutFor(saverPicture);
  const settings = toArtSettings(saverPicture);
  // The screen's size in picture units, for as many rings as fill it.
  const unitsPerPixel = bounds.height / sizeSaverFrame();
  const rings = art.wrapRingsToFill(settings, innerWidth * unitsPerPixel,
                                    innerHeight * unitsPerPixel);
  const copies = art.wrapCopies(settings, rings);
  const images = [];
  for (let i = 0; i < copies.length; i += 2) {
    const copy = new Image();
    copy.alt = '';
    copy.src = url;
    copy.style.transform = `translate(${(copies[i] / bounds.width) * 100}%, ` +
                           `${(copies[i + 1] / bounds.height) * 100}%)`;
    images.push(copy);
  }
  const picture = new Image();
  picture.alt = 'Animated turtle-art picture';
  picture.src = url;
  images.push(picture);  // Last, so it is drawn above its copies.
  $('saverFrame').replaceChildren(...images);
}

function nextSaverPicture() {
  clearTimeout(saverTimer);
  saverPicture = interestingSaverPicture();
  const svg = art.svg({ ...toArtSettings(saverPicture), hz: SCREENSAVER_HZ });
  // New images start their animation from the beginning: a clear grid.
  const old = saverUrl;
  saverUrl = URL.createObjectURL(new Blob([svg], { type: 'image/svg+xml' }));
  showSaverPicture(saverUrl);
  if (old) URL.revokeObjectURL(old);
  $('saverInfo').textContent = `#${saverPicture.seed}`;
  $('saverCommand').textContent = `${commandOf(saverPicture)} --hz ${SCREENSAVER_HZ}`;
  updateSaverFavorite();
  saverTimer = setTimeout(nextSaverPicture, (saverPicture.steps / SCREENSAVER_HZ) * 1000);
}

function startScreensaver() {
  $('screensaver').hidden = false;
  nextSaverPicture();
}

function stopScreensaver() {
  clearTimeout(saverTimer);
  $('screensaver').hidden = true;
}

function favoriteSaverPicture() {
  toggleFavorite(saverPicture);
  updateSaverFavorite();
}

// Shows or hides the HUD (buttons and command), leaving only the art.
function toggleSaverHud() {
  $('screensaver').classList.toggle('no-hud');
}

$('screensaverButton').addEventListener('click', startScreensaver);
// A new size may need more rings. The images reuse the same URL, so the
// animation carries on where it was.
window.addEventListener('resize', () => {
  if (!$('screensaver').hidden) showSaverPicture(saverUrl);
});
$('saverFav').addEventListener('click', favoriteSaverPicture);
$('saverNext').addEventListener('click', nextSaverPicture);
$('saverClose').addEventListener('click', stopScreensaver);
$('saverHud').addEventListener('click', toggleSaverHud);
// Clicking the art toggles the HUD too, so it can come back without keys.
$('saverFrame').addEventListener('click', toggleSaverHud);

// ---- Carpet: a still picture tiled over the screen, a new one every 10 s --
//
// Pictures come from a second worker (the first one serves the thumbnails),
// which tries random seeds until one is interesting enough. While one picture
// shows, the worker already looks for the next, so the swap is instant.
// Each picture fades in from black, stays, and fades back to black.

// A full picture, like SCREENSAVER.
const CARPET = {
  shape: 'golden', radius: 15, rows: 89, edge: 'wrap', paint: 'turtle',
  colors: 4, history: 2, steps: 155000,
};
const CARPET_MIN_INTEREST = 1.0;
const CARPET_PERIOD_MS = 10000;  // Per picture, fades included.
const CARPET_FADE_MS = 1000;     // As #carpetArt's transition in index.html.
const CARPET_PIXELS_PER_TILE = 2;
// The palette with black for unpainted tiles, which suits a dark carpet.
const CARPET_RGB = [[0, 0, 0], ...PALETTE_RGB.slice(1)];

const carpetWorker = new Worker(new URL('./worker.js', import.meta.url),
                                { type: 'module' });
let carpetRun = 0;        // Bumped on stop, so late answers are dropped.
let carpetPicture = null; // The picture showing.
let carpetUrl = null;     // Its image, as an object URL.
let carpetNext = null;    // {picture, url}: found, waiting to be shown.
let carpetWaiting = false;  // The screen is black, waiting for carpetNext.
let carpetTimer = null;

function findCarpetPicture() {
  const seed = Math.floor(Math.random() * 0x100000000);
  carpetWorker.postMessage({ run: carpetRun, picture: { ...CARPET, seed } });
}

carpetWorker.onmessage = async ({ data }) => {
  if (data.run !== carpetRun) return;
  if (data.entropy < CARPET_MIN_INTEREST) {
    findCarpetPicture();
    return;
  }
  const image = pixelImage(sizeOf(data.picture), data.colors, CARPET_RGB);
  const url = URL.createObjectURL(await image.convertToBlob());
  if (data.run !== carpetRun) {  // Stopped while the image was encoded.
    URL.revokeObjectURL(url);
    return;
  }
  carpetNext = { picture: data.picture, url };
  if (carpetWaiting) showNextCarpet();
};

// Sizes the repeated image so each tile is CARPET_PIXELS_PER_TILE screen
// pixels square. CSS pixels are devicePixelRatio screen pixels each.
function sizeCarpet() {
  if (!carpetPicture) return;
  const { width, height } = sizeOf(carpetPicture);
  const scale = CARPET_PIXELS_PER_TILE / devicePixelRatio;
  $('carpetArt').style.backgroundSize = `${width * scale}px ${height * scale}px`;
}

function updateCarpetFavorite() {
  $('carpetFav').textContent = isFavorite(carpetPicture) ? '★' : '☆';
}

// Fades in the picture found last, and starts looking for the next one.
function showNextCarpet() {
  carpetWaiting = false;
  const old = carpetUrl;
  ({ picture: carpetPicture, url: carpetUrl } = carpetNext);
  carpetNext = null;
  $('carpetArt').style.backgroundImage = `url(${carpetUrl})`;
  sizeCarpet();
  $('carpetArt').classList.add('shown');
  if (old) URL.revokeObjectURL(old);
  $('carpetInfo').textContent = `#${carpetPicture.seed}`;
  $('carpetCommand').textContent = commandOf(carpetPicture);
  updateCarpetFavorite();
  findCarpetPicture();
  carpetTimer = setTimeout(hideCarpet, CARPET_PERIOD_MS - CARPET_FADE_MS);
}

// Fades to black, then shows the next picture, or waits for it.
function hideCarpet() {
  clearTimeout(carpetTimer);
  $('carpetArt').classList.remove('shown');
  carpetTimer = setTimeout(() => {
    if (carpetNext) showNextCarpet();
    else carpetWaiting = true;
  }, CARPET_FADE_MS);
}

function startCarpet() {
  $('carpet').hidden = false;
  $('carpetInfo').textContent = 'finding a picture…';
  carpetWaiting = true;
  findCarpetPicture();
}

function stopCarpet() {
  clearTimeout(carpetTimer);
  carpetRun++;
  carpetWaiting = false;
  if (carpetNext) URL.revokeObjectURL(carpetNext.url);
  carpetNext = null;
  $('carpetArt').classList.remove('shown');
  $('carpet').hidden = true;
}

// Skips to the next picture, unless already between pictures.
function nextCarpet() {
  if ($('carpetArt').classList.contains('shown')) hideCarpet();
}

function favoriteCarpetPicture() {
  if (!carpetPicture) return;
  toggleFavorite(carpetPicture);
  updateCarpetFavorite();
}

function toggleCarpetHud() {
  $('carpet').classList.toggle('no-hud');
}

$('carpetButton').addEventListener('click', startCarpet);
window.addEventListener('resize', sizeCarpet);  // Also on zoom: new ratio.
$('carpetFav').addEventListener('click', favoriteCarpetPicture);
$('carpetNext').addEventListener('click', nextCarpet);
$('carpetClose').addEventListener('click', stopCarpet);
$('carpetHud').addEventListener('click', toggleCarpetHud);
$('carpetArt').addEventListener('click', toggleCarpetHud);

document.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;
  if (!$('carpet').hidden) {
    const carpetActions = {
      Escape: stopCarpet, f: favoriteCarpetPicture, n: nextCarpet,
      h: toggleCarpetHud,
    };
    if (carpetActions[e.key]) {
      e.preventDefault();
      carpetActions[e.key]();
    }
    return;
  }
  if (!$('screensaver').hidden) {
    const saverActions = {
      Escape: stopScreensaver, f: favoriteSaverPicture, n: nextSaverPicture,
      h: toggleSaverHud,
    };
    if (saverActions[e.key]) {
      e.preventDefault();
      saverActions[e.key]();
    }
    return;
  }
  if ($('viewer').hidden) {
    if (e.key === 'g') toggleFavoritesView();
    if (e.key === 'r') randomStart();
    if (e.key === 's') startScreensaver();
    if (e.key === 'c') startCarpet();
    // Enter opens the first picture, to browse with the keyboard alone.
    if (e.key === 'Enter' && items.length > 0) openViewer(0);
    return;
  }
  const actions = {
    ArrowLeft: () => step(-1), ArrowRight: () => step(1),
    f: favoriteCurrent, d: downloadCurrent, p: () => downloadPngCurrent(),
    c: copyCurrent, Escape: closeViewer,
  };
  if (actions[e.key]) {
    e.preventDefault();
    actions[e.key]();
  }
});

// ---- Start -------------------------------------------------------------------

// All but the last, which has no next Fibonacci number for the width.
for (const rows of FIBONACCI.slice(0, -1)) $('rows').add(new Option(rows, rows));
writeControls(settings);
applyControls();
